(function(){
const LEVELS={basic:{icon:'🟢',latn:'Osnovni',cyrl:'Основни'},medium:{icon:'🟡',latn:'Srednji',cyrl:'Средњи'},advanced:{icon:'🔴',latn:'Napredni',cyrl:'Напредни'},adaptive:{icon:'🎯',latn:'Prilagođeni',cyrl:'Прилагођени'}};
let areaId='geometrija',config=null,session=null,currentAttempts=0,currentResolved=false,hintShown=false;
function script(){return window.getSiteScript?.()==='latn'?'latn':'cyrl'}
function tx(latn,cyrl){return script()==='latn'?latn:cyrl}
function pick(pair){return pair?.[script()==='latn'?0:1]||''}
function progressApi(){return window.MatematikONProgress}
function read(){return progressApi()?.read()||{practice:{areas:{}},tests:{}}}
function write(value){return progressApi()?.write(value)}
function areaData(state=read(),id=areaId){state.practice=state.practice||{areas:{}};state.practice.areas=state.practice.areas||{};state.practice.areas[id]=state.practice.areas[id]||{sessions:[],topics:{},types:{},recent:[],lastLevel:'basic'};const data=state.practice.areas[id];data.types=data.types||{};data.recent=data.recent||[];return data}
function statsSummary(id=areaId){const state=read(),data=areaData(state,id),topics=data.topics||{},attempted=Object.values(topics).reduce((n,x)=>n+(x.attempted||0),0),hasStruggle=Object.values(topics).some(x=>(x.correct||0)<(x.attempted||0)||(x.wrongAttempts||0)>0||(x.solutions||0)>0),testId=(config||window.MatematikONPracticeAreas?.[id])?.testId||('test-'+id),testRecommendations=state.tests?.[testId]?.recommendations||[];return{attempted,topics,testRecommendations,enough:(attempted>=10&&hasStruggle)||testRecommendations.length>0}}
function topicScore(slug,summary){const s=summary.topics[slug]||{},attempted=s.attempted||0,accuracy=attempted?(s.correct||0)/attempted:1,errors=s.wrongAttempts||0,solutions=s.solutions||0,testBoost=summary.testRecommendations.includes(slug)?3:0;return(1-accuracy)*5+errors/Math.max(1,attempted)+solutions*1.5+testBoost}
function weakTopics(id=areaId){const cfg=config||window.MatematikONPracticeAreas?.[id],summary=statsSummary(id),known=new Set([...Object.keys(summary.topics),...summary.testRecommendations]);return [...known].filter(slug=>cfg?.topics[slug]&&topicScore(slug,summary)>0).sort((a,b)=>topicScore(b,summary)-topicScore(a,summary))}
function shuffled(items){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function makePlan(level,mode='normal'){const cfg=config||window.MatematikONPracticeAreas?.[areaId],planner=window.MatematikONPracticePlanner;if(!planner)return[];return planner.buildPlan({config:cfg,level,mode,history:areaData().recent,weakTopics:mode==='weak'?weakTopics():[],count:10})}
function templateById(id){const cfg=config||window.MatematikONPracticeAreas?.[areaId];return cfg.templates.find(t=>t.id===id)}
function questionAt(index=session.index){recordExposure();const item=session.items[index],template=templateById(item.templateId),question=config.build(template,item.variantIndex);question.typeKind=template.typeKind||'direct';question.sourceTypeId=template.sourceTypeId||template.id;return question}
function recordExposure(){const item=session.items[session.index],template=templateById(item.templateId);item.key=item.key||item.templateId+':'+item.variantIndex;item.contentKey=item.contentKey||(template.sourceTypeId||template.id)+':'+item.variantIndex;session.exposed=session.exposed||{};if(session.exposed[session.index]===item.key)return;const state=read(),data=areaData(state),row={templateId:item.templateId,variantIndex:item.variantIndex,key:item.key,contentKey:item.contentKey,shownAt:new Date().toISOString()};data.recent=[row,...data.recent.filter(x=>x.key!==row.key)].slice(0,80);session.exposed[session.index]=item.key;data.active=session;write(state)}
function saveActive(){const state=read(),data=areaData(state);data.active=session;data.lastLevel=session.level==='adaptive'?(data.lastLevel||'basic'):session.level;write(state)}
function clearActiveAndSaveResults(){const state=read(),data=areaData(state);delete data.active;data.sessions=data.sessions||[];const completed={id:session.id,date:new Date().toISOString(),level:session.level,mode:session.mode,correct:session.results.filter(x=>x.correct).length,total:10,results:session.results};data.sessions.unshift(completed);data.sessions=data.sessions.slice(0,20);data.topics=data.topics||{};data.types=data.types||{};session.results.forEach(result=>{const topic=data.topics[result.topic]||(data.topics[result.topic]={attempted:0,correct:0,wrongAttempts:0,hints:0,solutions:0}),type=data.types[result.templateId]||(data.types[result.templateId]={attempted:0,correct:0,wrongAttempts:0,hints:0,solutions:0});for(const stat of [topic,type]){stat.attempted++;if(result.correct)stat.correct++;stat.wrongAttempts+=result.wrongAttempts||0;if(result.hintUsed)stat.hints++;if(result.usedSolution)stat.solutions++}});write(state);return completed}
function start(level,mode='normal'){const items=makePlan(level,mode);session={id:'practice-'+Date.now(),area:areaId,level:mode==='weak'?'adaptive':level,mode,index:0,items,results:[],exposed:{}};currentAttempts=0;currentResolved=false;hintShown=false;saveActive();renderQuestion()}
function restore(active){if(!active?.items?.every(item=>templateById(item.templateId))){const state=read();delete areaData(state).active;write(state);session=null;renderSetup(tx('Prethodna započeta sesija je osvežena. Izaberi nivo za novu sesiju.','Претходна започета сесија је освежена. Изабери ниво за нову сесију.'));return}session=active;session.results=session.results||[];const draft=session.current?.index===session.index?session.current:null,saved=session.results[session.index];currentAttempts=saved?.wrongAttempts||draft?.attempts||0;currentResolved=Boolean(saved);hintShown=Boolean(saved?.hintUsed||draft?.hintShown);renderQuestion(true);if(saved?.usedSolution)showSolution(questionAt())}
function levelLabel(level){const item=LEVELS[level];return item.icon+' '+(script()==='latn'?item.latn:item.cyrl)}
function shell(content){const main=document.querySelector('#smart-practice-main');main.innerHTML=`<section class="smart-practice-page"><div class="wrap"><nav class="breadcrumbs"><a href="/">${tx('Početna','Почетна')}</a><span>›</span><a href="/oblast.html?oblast=${areaId}">${pick(config.title)}</a><span>›</span><strong>${tx('Pametno vežbanje','Паметно вежбање')}</strong></nav>${content}</div></section>`}
function renderSetup(message=''){const summary=statsSummary(),active=areaData().active;shell(`<header class="smart-head"><p class="eyebrow">${tx('PAMETNO VEŽBANJE V1','ПАМЕТНО ВЕЖБАЊЕ V1')}</p><h1>${pick(config.title)}</h1><p>${tx('Izaberi nivo i reši kratku sesiju od 10 zadataka. Pomoć se otvara postepeno, tek kada ti zatreba.','Изабери ниво и реши кратку сесију од 10 задатака. Помоћ се отвара постепено, тек када ти затреба.')}</p></header>${message?`<p class="practice-notice">${message}</p>`:''}${active?`<button class="resume-session" type="button">▶ ${tx('Nastavi započetu sesiju','Настави започету сесију')} — ${levelLabel(active.level)}</button>`:''}<div class="level-grid"><button class="level-card basic" data-start="basic"><span>🟢</span><strong>${tx('Osnovni','Основни')}</strong><small>${tx('Osnovno razumevanje i direktna primena.','Основно разумевање и директна примена.')}</small></button><button class="level-card medium" data-start="medium"><span>🟡</span><strong>${tx('Srednji','Средњи')}</strong><small>${tx('Povezivanje znanja i zadaci sa više koraka.','Повезивање знања и задаци са више корака.')}</small></button><button class="level-card advanced" data-start="advanced"><span>🔴</span><strong>${tx('Napredni','Напредни')}</strong><small>${tx('Složeniji problemski zadaci iz gradiva 5. razreda.','Сложенији проблемски задаци из градива 5. разреда.')}</small></button></div><div class="weak-start ${summary.enough?'ready':'locked'}"><div><strong>🎯 ${tx('Vežbaj slabe tačke','Вежбај слабе тачке')}</strong><p>${summary.enough?tx('Zadaci će dati prednost temama u kojima si imao najviše poteškoća.','Задаци ће дати предност темама у којима си имао највише потешкоћа.'):tx('Prvo završi jednu sesiju od 10 zadataka ili završni test oblasti.','Прво заврши једну сесију од 10 задатака или завршни тест области.')}</p></div><button type="button" data-start-weak ${summary.enough?'':'disabled'}>${tx('Pokreni','Покрени')}</button></div>`);document.querySelectorAll('[data-start]').forEach(button=>button.addEventListener('click',()=>start(button.dataset.start)));document.querySelector('[data-start-weak]')?.addEventListener('click',()=>start(areaData().lastLevel||'medium','weak'));document.querySelector('.resume-session')?.addEventListener('click',()=>restore(active))}
function questionMarkup(question){const input=question.kind==='number'?`<form class="practice-answer-form"><label for="practice-answer">${tx('Tvoj odgovor','Твој одговор')}</label><div><input id="practice-answer" inputmode="decimal" autocomplete="off" aria-describedby="practice-unit"><span id="practice-unit">${question.unit||''}</span><button type="submit">${tx('Proveri','Провери')}</button></div></form>`:`<div class="practice-choices" role="group" aria-label="${tx('Izaberi odgovor','Изабери одговор')}">${question.choices.map(option=>`<button type="button" data-choice="${option.value}">${pick(option.label)}</button>`).join('')}</div>`;return`${question.diagram?`<div class="practice-diagram">${question.diagram}</div>`:''}<div class="practice-prompt">${pick(question.prompt)}</div>${input}`}
function renderQuestion(restored=false){const question=questionAt(),number=session.index+1,actualLevel=session.level==='adaptive'?question.level:session.level;shell(`<div class="practice-session-head"><div><span class="level-pill ${actualLevel}">${levelLabel(actualLevel)}</span><h1>${tx('Zadatak','Задатак')} ${number} ${tx('od','од')} 10</h1></div><button class="exit-practice" type="button">${tx('Promeni nivo','Промени ниво')}</button></div><div class="session-progress" role="progressbar" aria-valuemin="1" aria-valuemax="10" aria-valuenow="${number}"><i style="width:${number*10}%"></i></div><article class="smart-question-card" data-topic="${question.topic}">${questionMarkup(question)}<div class="practice-feedback" aria-live="polite"></div><div class="help-actions"><button type="button" data-hint hidden>💡 ${tx('Nagoveštaj','Наговештај')}</button><button type="button" data-solution hidden>${tx('Prikaži postupak','Прикажи поступак')}</button></div><div class="help-panel" hidden></div><div class="question-actions"><button type="button" class="new-variant">↻ ${tx('Novi zadatak','Нови задатак')}</button><button type="button" class="next-practice" hidden>${number===10?tx('Završi sesiju','Заврши сесију'):tx('Sledeći zadatak','Следећи задатак')} →</button></div></article>`);bindQuestion(question);if(restored&&currentResolved){const saved=session.results[session.index],feedback=document.querySelector('.practice-feedback'),solved=saved.correct||saved.solved;feedback.className='practice-feedback '+(solved?'correct':'solution');feedback.textContent=saved.correct?tx('Tačno! Odgovor je sačuvan.','Тачно! Одговор је сачуван.'):solved?tx('Zadatak je rešen. Rezultat se računa prema prvom pokušaju.','Задатак је решен. Резултат се рачуна према првом покушају.'):tx('Postupak je prikazan. Odgovor je sačuvan.','Поступак је приказан. Одговор је сачуван.');disableAnswer();document.querySelector('.new-variant').hidden=true;document.querySelector('.next-practice').hidden=false}else if(restored){if(currentAttempts>=2)document.querySelector('[data-hint]').hidden=hintShown;if(currentAttempts>=3)document.querySelector('[data-solution]').hidden=false;if(hintShown)showHint(question)}}
function parseNumber(value){const cleaned=value.trim().replace(',','.').replace(/[^0-9.\-]/g,'');return cleaned===''?NaN:Number(cleaned)}
function answerIsCorrect(question,value){return question.kind==='number'?Math.abs(parseNumber(value)-question.answer)<1e-9:String(value)===String(question.answer)}
function bindQuestion(question){document.querySelector('.practice-answer-form')?.addEventListener('submit',event=>{event.preventDefault();attempt(question,document.querySelector('#practice-answer').value)});document.querySelectorAll('[data-choice]').forEach(button=>button.addEventListener('click',()=>attempt(question,button.dataset.choice,button)));document.querySelector('[data-hint]').addEventListener('click',()=>showHint(question));document.querySelector('[data-solution]').addEventListener('click',()=>showSolution(question));document.querySelector('.new-variant').addEventListener('click',newVariant);document.querySelector('.next-practice').addEventListener('click',nextQuestion);document.querySelector('.exit-practice').addEventListener('click',()=>{session=null;renderSetup()})}
function attempt(question,value,button){if(currentResolved)return;const feedback=document.querySelector('.practice-feedback');if(answerIsCorrect(question,value)){const firstTry=currentAttempts===0;currentResolved=true;feedback.className='practice-feedback correct';feedback.textContent=firstTry?tx('Tačno! Bravo.','Тачно! Браво.'):tx('Tačno! Zadatak je rešen.','Тачно! Задатак је решен.');button?.classList.add('chosen-correct');session.results[session.index]={topic:question.topic,templateId:question.templateId,level:question.level,correct:firstTry,solved:true,wrongAttempts:currentAttempts,hintUsed:hintShown,usedSolution:false};delete session.current;saveActive();disableAnswer();document.querySelector('.new-variant').hidden=true;document.querySelector('.next-practice').hidden=false;return}currentAttempts++;session.current={index:session.index,attempts:currentAttempts,hintShown};saveActive();button?.classList.add('chosen-wrong');setTimeout(()=>button?.classList.remove('chosen-wrong'),450);feedback.className='practice-feedback wrong';feedback.textContent=currentAttempts===1?tx('Nije tačno. Pokušaj još jednom.','Није тачно. Покушај још једном.'):currentAttempts===2?tx('Još nije tačno. Možeš da zatražiš nagoveštaj.','Још није тачно. Можеш да затражиш наговештај.'):tx('Pokušaj još jednom ili pogledaj postupak.','Покушај још једном или погледај поступак.');if(currentAttempts>=2)document.querySelector('[data-hint]').hidden=false;if(currentAttempts>=3)document.querySelector('[data-solution]').hidden=false}
function showHint(question){hintShown=true;session.current={index:session.index,attempts:currentAttempts,hintShown};saveActive();const panel=document.querySelector('.help-panel');panel.hidden=false;panel.className='help-panel hint';panel.innerHTML=`<strong>💡 ${tx('Nagoveštaj','Наговештај')}</strong><p>${pick(question.hint)}</p>`;document.querySelector('[data-hint]').hidden=true}
function displayAnswer(question){if(question.kind==='choice'){const option=question.choices.find(x=>x.value===question.answer);return option?pick(option.label):question.answer}return question.answer+(question.unit||'')}
function showSolution(question){currentResolved=true;const panel=document.querySelector('.help-panel');panel.hidden=false;panel.className='help-panel solution';panel.innerHTML=`<strong>${tx('Postupak','Поступак')}</strong><ol>${question.steps.map(step=>`<li>${pick(step)}</li>`).join('')}</ol><p><b>${tx('Tačan odgovor','Тачан одговор')}:</b> ${displayAnswer(question)}</p>`;session.results[session.index]={topic:question.topic,templateId:question.templateId,level:question.level,correct:false,wrongAttempts:currentAttempts,hintUsed:hintShown,usedSolution:true};delete session.current;saveActive();disableAnswer();document.querySelector('.new-variant').hidden=true;document.querySelector('[data-hint]').hidden=true;document.querySelector('[data-solution]').hidden=true;document.querySelector('.next-practice').hidden=false}
function disableAnswer(){document.querySelectorAll('.practice-choices button,.practice-answer-form input,.practice-answer-form button').forEach(el=>el.disabled=true)}
function newVariant(){const item=session.items[session.index],planner=window.MatematikONPracticePlanner,next=planner?.alternate({config,current:item,items:session.items.filter((_,index)=>index!==session.index),history:areaData().recent})||item;session.items[session.index]=next;currentAttempts=0;currentResolved=false;hintShown=false;delete session.results[session.index];delete session.current;if(session.exposed)delete session.exposed[session.index];saveActive();renderQuestion()}
function nextQuestion(){if(!currentResolved)return;if(session.index<9){session.index++;currentAttempts=session.results[session.index]?.wrongAttempts||0;currentResolved=Boolean(session.results[session.index]);hintShown=Boolean(session.results[session.index]?.hintUsed);delete session.current;saveActive();renderQuestion(Boolean(currentResolved))}else finishSession()}
function resultGroups(results=session.results){const grouped={};results.forEach(r=>{const x=grouped[r.topic]||(grouped[r.topic]={total:0,correct:0,wrong:0});x.total++;if(r.correct)x.correct++;x.wrong+=r.wrongAttempts+(r.usedSolution?2:0)});const entries=Object.entries(grouped),good=entries.filter(([,x])=>x.correct===x.total&&x.wrong<=1).map(([slug])=>slug),problems=entries.filter(([,x])=>x.correct<x.total||x.wrong>=2).sort((a,b)=>b[1].wrong-a[1].wrong).map(([slug])=>slug);return{good,problems}}
function recommendation(score){if(score>=9)return tx('Odlično! Spreman si za teži nivo.','Одлично! Спреман си за тежи ниво.');if(score>=7)return tx('Vrlo dobro. Možeš nastaviti ili pokušati teži nivo.','Врло добро. Можеш наставити или покушати тежи ниво.');if(score>=5)return tx('Dobro, ali preporučujemo još malo vežbanja.','Добро, али препоручујемо још мало вежбања.');return tx('Vrati se na preporučene lekcije i pokušaj ponovo.','Врати се на препоручене лекције и покушај поново.')}
function renderFinishedSession(){const score=session.results.filter(x=>x.correct).length,solved=session.results.filter(x=>x.correct||x.solved).length,percent=score*10,groups=resultGroups(),links=groups.problems.slice(0,4).map(slug=>`<li><a href="/lekcija.html?id=${encodeURIComponent(slug)}">${pick(config.topics[slug])}</a></li>`).join('');shell(`<section class="practice-result"><span class="result-medal">${score>=9?'★':score>=7?'✓':'∑'}</span><p class="eyebrow">${tx('SESIJA JE ZAVRŠENA','СЕСИЈА ЈЕ ЗАВРШЕНА')}</p><h1>${score}/10</h1><p class="first-try-note">${tx('Tačno iz prvog pokušaja','Тачно из првог покушаја')}</p><div class="result-metrics smart"><p><span>${tx('Uspešnost','Успешност')}</span><b>${percent}%</b></p><p><span>${tx('Nivo','Ниво')}</span><b>${levelLabel(session.level)}</b></p></div>${solved>score?`<p class="eventual-score">${tx('Na kraju uspešno rešeno','На крају успешно решено')}: <strong>${solved}/10</strong></p>`:''}<p class="session-advice">${recommendation(score)}</p>${groups.good.length?`<div class="topic-result good"><strong>${tx('Dobro ti idu:','Добро ти иду:')}</strong><p>${groups.good.map(slug=>pick(config.topics[slug])).join(' · ')}</p></div>`:''}${links?`<div class="topic-result repeat"><strong>${tx('Preporučujemo da ponoviš:','Препоручујемо да поновиш:')}</strong><ul>${links}</ul></div>`:''}<div class="result-actions"><button type="button" data-repeat>${tx('Nova sesija','Нова сесија')}</button><a href="/oblast.html?oblast=${areaId}">${tx('Pregled oblasti','Преглед области')}</a></div></section>`);document.querySelector('[data-repeat]').addEventListener('click',()=>{session=null;renderSetup()})}
function finishSession(){clearActiveAndSaveResults();session.finished=true;renderFinishedSession()}
function enhanceArea(id){const target=document.querySelector('[data-smart-practice-area]'),cfg=window.MatematikONPracticeAreas?.[id];if(!target)return;if(!cfg){target.innerHTML='';return}const oldConfig=config;config=cfg;const summary=statsSummary(id),rows=Object.entries(summary.topics).filter(([,s])=>s.attempted).sort((a,b)=>b[1].attempted-a[1].attempted).slice(0,3).map(([slug,s])=>`<li><span>${pick(cfg.topics[slug])}</span><b>${s.correct}/${s.attempted} · ${Math.round(s.correct/s.attempted*100)}%</b></li>`).join('');target.innerHTML=`<section class="smart-area-card"><div><span class="smart-icon">✦</span><div><small>${tx('PAMETNO VEŽBANJE V1','ПАМЕТНО ВЕЖБАЊЕ V1')}</small><h2>${tx('Vežbaj prema svom znanju','Вежбај према свом знању')}</h2><p>${tx('Izaberi nivo, dobijaj pomoć korak po korak i saznaj koje teme treba da ponoviš.','Изабери ниво, добијај помоћ корак по корак и сазнај које теме треба да поновиш.')}</p></div></div><div class="smart-area-actions"><a class="smart-primary" href="/pametno-vezbanje.html?oblast=${id}">${tx('Pokreni vežbanje','Покрени вежбање')} →</a><a class="smart-weak ${summary.enough?'':'disabled'}" ${summary.enough?`href="/pametno-vezbanje.html?oblast=${id}&mode=weak" aria-disabled="false"`:'aria-disabled="true"'}>🎯 ${tx('Vežbaj slabe tačke','Вежбај слабе тачке')}</a></div>${rows?`<div class="smart-topic-stats"><strong>${tx('Dosadašnji rezultati','Досадашњи резултати')}</strong><ul>${rows}</ul></div>`:!summary.enough?`<p class="smart-empty">${tx('Slabe tačke će se aktivirati posle prve sesije od 10 zadataka.','Слабе тачке ће се активирати после прве сесије од 10 задатака.')}</p>`:''}</section>`;config=oldConfig}
function validateAll(id='geometrija'){const cfg=window.MatematikONPracticeAreas?.[id];if(!cfg)return[];const errors=[];cfg.templates.forEach(template=>template.variants.forEach((_,index)=>{const q=cfg.build(template,index);if(!cfg.validate(q))errors.push(template.id+':'+index)}));return errors}
function init(){const main=document.querySelector('#smart-practice-main');if(!main)return;const params=new URLSearchParams(location.search),requested=params.get('oblast')||'geometrija';areaId=window.MatematikONPracticeAreas?.[requested]?requested:'geometrija';config=window.MatematikONPracticeAreas?.[areaId];if(!config){main.innerHTML='<p>Садржај није доступан.</p>';return}window.renderRouteText=()=>{if(session)session.finished?renderFinishedSession():restore(session);else renderSetup()};document.title=tx('Pametno vežbanje — MatematikON','Паметно вежбање — MatematikON');const active=areaData().active;if(active)restore(active);else if(params.get('mode')==='weak'){statsSummary().enough?start(areaData().lastLevel||'medium','weak'):renderSetup(tx('Prvo završi jednu sesiju da bismo prepoznali slabe tačke.','Прво заврши једну сесију да бисмо препознали слабе тачке.'))}else renderSetup()}
window.MatematikONSmartPractice={enhanceArea,statsSummary,weakTopics,makePlan,validateAll,answerIsCorrect,resultGroups,recommendation,init};
if(document.body?.dataset.page==='smart-practice')init();
})();
